func Test_shouldDownload(t *testing.T) {
	type args struct {
		vuls2Conf config.Vuls2Conf
		now       time.Time
	}
	tests := []struct {
		name     string
		args     args
		metadata *types.Metadata
		want     bool
		wantErr  bool
		errText  string
	}{
		{
			name: "no db file",
			args: args{
				vuls2Conf: config.Vuls2Conf{},
				now:       *parse("2024-01-02T00:00:00Z"),
			},
			want: true,
		},
		{
			name: "no db file, but skip update",
			args: args{
				vuls2Conf: config.Vuls2Conf{
					SkipUpdate: true,
				},
				now: *parse("2024-01-02T00:00:00Z"),
			},
			wantErr: true,
		},
		{
			name: "schema mismatch forces download even when recently downloaded",
			args: args{
				vuls2Conf: config.Vuls2Conf{},
				now:       *parse("2024-01-02T00:00:00Z"),
			},
			metadata: &types.Metadata{
				LastModified:  *parse("2024-01-02T00:00:00Z"),
				Downloaded:    parse("2024-01-02T00:00:00Z"),
				SchemaVersion: common.SchemaVersion + 1,
			},
			want: true,
		},
		{
			name: "schema mismatch cannot skip update",
			args: args{
				vuls2Conf: config.Vuls2Conf{SkipUpdate: true},
				now:       *parse("2024-01-02T00:00:00Z"),
			},
			metadata: &types.Metadata{
				LastModified:  *parse("2024-01-02T00:00:00Z"),
				Downloaded:    parse("2024-01-02T00:00:00Z"),
				SchemaVersion: common.SchemaVersion + 1,
			},
			wantErr: true,
			errText: "schema version mismatch",
		},
		{
			name: "just created",
			args: args{
				vuls2Conf: config.Vuls2Conf{},
				now:       *parse("2024-01-02T00:00:00Z"),
			},
			metadata: &types.Metadata{
				LastModified:  *parse("2024-01-02T00:00:00Z"),
				Downloaded:    parse("2024-01-02T00:00:00Z"),
				SchemaVersion: common.SchemaVersion,
			},
			want: false,
		},
		{
			name: "8 hours old",
			args: args{
				vuls2Conf: config.Vuls2Conf{},
				now:       *parse("2024-01-02T08:00:00Z"),
			},
			metadata: &types.Metadata{
				LastModified:  *parse("2024-01-02T00:00:00Z"),
				Downloaded:    parse("2024-01-02T00:00:00Z"),
				SchemaVersion: common.SchemaVersion,
			},
			want: true,
		},
		{
			name: "8 hours old, but skip update",
			args: args{
				vuls2Conf: config.Vuls2Conf{
					SkipUpdate: true,
				},
				now: *parse("2024-01-02T08:00:00Z"),
			},
			metadata: &types.Metadata{
				LastModified:  *parse("2024-01-02T00:00:00Z"),
				Downloaded:    parse("2024-01-02T00:00:00Z"),
				SchemaVersion: common.SchemaVersion,
			},
			want: false,
		},
		{
			name: "8 hours old, but download recently",
			args: args{
				vuls2Conf: config.Vuls2Conf{},
				now:       *parse("2024-01-02T08:00:00Z"),
			},
			metadata: &types.Metadata{
				LastModified:  *parse("2024-01-02T00:00:00Z"),
				Downloaded:    parse("2024-01-02T07:30:00Z"),
				SchemaVersion: common.SchemaVersion,
			},
			want: false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			d := t.TempDir()
			tt.args.vuls2Conf.Path = filepath.Join(d, "vuls.db")
			if tt.metadata != nil {
				if err := putMetadata(*tt.metadata, tt.args.vuls2Conf.Path); err != nil {
					t.Errorf("putMetadata err = %v", err)
					return
				}
			}
			got, err := vuls2.ShouldDownload(tt.args.vuls2Conf, tt.args.now)
			if (err != nil) != tt.wantErr {
				t.Errorf("shouldDownload() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if tt.errText != "" && (!strings.Contains(err.Error(), tt.errText) || !strings.Contains(err.Error(), tt.args.vuls2Conf.Path)) {
				t.Errorf("shouldDownload() error = %v, want text %q and path %q", err, tt.errText, tt.args.vuls2Conf.Path)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("shouldDownload() = %v, want %v", got, tt.want)
			}
		})
	}

}

func Test_newDBConnection(t *testing.T) {
	path := filepath.Join(t.TempDir(), "vuls.db")
	if err := putMetadata(types.Metadata{SchemaVersion: common.SchemaVersion}, path); err != nil {
		t.Fatal(err)
	}

	dbc, err := vuls2.NewDBConnection(config.Vuls2Conf{Path: path, SkipUpdate: true}, true)
	if err != nil {
		t.Fatal(err)
	}
	if err := dbc.Open(); err != nil {
		t.Fatalf("returned connection could not be opened: %v", err)
	}
	defer dbc.Close()
	metadata, err := dbc.GetMetadata()
	if err != nil {
		t.Fatal(err)
	}
	if metadata.SchemaVersion != common.SchemaVersion {
		t.Errorf("schema version = %d, want %d", metadata.SchemaVersion, common.SchemaVersion)
	}
}

func putMetadata(metadata types.Metadata, path string) error {
	c := common.Config{
		Type: "boltdb",
		Path: path,
	}
	dbc, err := c.New()
	if err != nil {
		return xerrors.Errorf("c.New(). err: %w", err)
	}
	if err := dbc.Open(); err != nil {
		return xerrors.Errorf("dbc.Open(). err: %w", err)
	}
	defer dbc.Close()
	if err := dbc.Initialize(); err != nil {
		return xerrors.Errorf("dbc.Initialize(). err: %w", err)
	}
	if err := dbc.PutMetadata(metadata); err != nil {
		return xerrors.Errorf("dbc.PutMetadata(). err: %w", err)
	}
	return nil
}

